import { createClient } from "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.119.0/+esm";
import {APP_CONFIG} from "./config.js";
const db=createClient(APP_CONFIG.supabaseUrl,APP_CONFIG.supabaseAnonKey),$=s=>document.querySelector(s);
let user=null,mode="signin",page="overview",cache={};
const pages={overview:["Overview","Your business command centre"],opportunities:["Opportunities","Find work, publish opportunities and apply"],services:["My services","Turn what you know into a clear offer customers can buy"],skills:["My skills","Show customers what you can do"],leads:["Customer pipeline","Manage conversations and follow-ups"],applications:["Applications & saves","Track applications and saved opportunities"],assistant:["Sales studio","Prepare customer pitches, proposals and quotes"],earnings:["Income tracker","Know what you have earned and what is still outstanding"],profile:["Your profile","Build trust with a complete professional profile"]};
$("#year").textContent=new Date().getFullYear();
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=(v,c="KES")=>{try{return new Intl.NumberFormat(undefined,{style:"currency",currency:c}).format(Number(v||0))}catch{return Number(v||0).toFixed(2)+" "+c}};
function toast(t){const e=$("#toast");e.textContent=t;e.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove("show"),2800)}
function fail(e){console.error(e);toast(e.message||"Something went wrong")}
function setMode(m){mode=m;document.querySelectorAll("[data-mode]").forEach(x=>x.classList.toggle("selected",x.dataset.mode===m));$("#name-row").classList.toggle("hidden",m!=="signup");$("#auth-title").textContent=m==="signin"?"Welcome back":"Create your EarnBridge account";$("#auth-submit").textContent=m==="signin"?"Sign in":"Create account";$("#auth-error").textContent=""}
document.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
const authForm=$("#auth-form");
authForm.addEventListener("submit",async e=>{
 e.preventDefault();e.stopPropagation();
 const btn=$("#auth-submit"),err=$("#auth-error"),note=$("#auth-note");
 const email=$("#email").value.trim().toLowerCase(),password=$("#password").value;
 err.textContent="";
 if(!email||!password){err.textContent="Enter your email address and password.";return}
 btn.disabled=true;btn.textContent=mode==="signin"?"Signing in…":"Creating account…";
 note.textContent="Connecting securely to EarnBridge…";
 try{
  const result=mode==="signup"
   ?await db.auth.signUp({email,password,options:{data:{full_name:$("#full-name").value.trim()}}})
   :await db.auth.signInWithPassword({email,password});
  if(result.error)throw result.error;
  if(result.data?.session&&result.data?.user){
   user=result.data.user;await ensureProfile();showApp();
  }else if(mode==="signup"){
   note.textContent="Check your inbox for the confirmation email.";
   err.textContent="Account created. Confirm your email, then return here and sign in.";
  }else{
   err.textContent="No active session was returned. Check your Supabase Auth settings and try again.";
  }
 }catch(x){
  console.error("EarnBridge authentication failed:",x);
  err.textContent=x?.message||"Sign-in failed. Please try again.";
  note.textContent="Please check your details and try again.";
 }finally{
  btn.disabled=false;btn.innerHTML=(mode==="signin"?"Sign in":"Create account")+' <span>→</span>';
 }
});
window.EB_AUTH_READY=true;
async function ensureProfile(){const {data,error}=await db.from("eb_profiles").select("id").eq("id",user.id).maybeSingle();if(error)throw error;if(!data){const r=await db.from("eb_profiles").insert({id:user.id,full_name:user.user_metadata?.full_name||""});if(r.error)throw r.error}}
function showAuth(){$("#auth").classList.remove("hidden");$("#app").classList.add("hidden");$("#logout").classList.add("hidden")}
function showApp(){$("#auth").classList.add("hidden");$("#app").classList.remove("hidden");$("#logout").classList.remove("hidden");$("#user-label").textContent=user.email;render()}
$("#logout").onclick=async()=>{await db.auth.signOut();user=null;showAuth()};
document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page));
function go(p){page=p;document.querySelectorAll("[data-page]").forEach(x=>x.classList.toggle("active",x.dataset.page===p));render();window.scrollTo({top:0,behavior:"smooth"})}
function head(){return '<div class="page-head"><div><div class="eyebrow">EARNBRIDGE WORKSPACE</div><h1>'+pages[page][0]+'</h1><p>'+pages[page][1]+'</p></div><div class="head-date">'+new Date().toLocaleDateString(undefined,{weekday:"short",day:"numeric",month:"short"})+'</div></div>'}
function stat(label,value,sub,icon){return '<div class="stat-card"><div class="stat-icon">'+icon+'</div><div class="stat-label">'+label+'</div><div class="stat-value">'+value+'</div><div class="stat-sub">'+sub+'</div></div>'}
function empty(title,sub="Your records will appear here once you add them."){return '<div class="empty-state"><div class="empty-icon">✦</div><h3>'+title+'</h3><p>'+sub+'</p></div>'}
function shell(html){$("#content").innerHTML=head()+html}
async function get(table,order="created_at"){const {data,error}=await db.from(table).select("*").order(order,{ascending:false});if(error)throw error;cache[table]=data||[];return cache[table]}
async function render(){shell('<div class="loading">Loading your workspace…</div>');try{await ({overview,opportunities,services,skills,leads,applications,assistant,earnings,profile}[page])()}catch(e){shell(empty("We couldn't load this section",e.message));console.error(e)}}
function bindDelete(table,refresh){document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=async()=>{if(!confirm("Delete this record permanently?"))return;const {error}=await db.from(table).delete().eq("id",b.dataset.delete);if(error)return fail(error);toast("Record deleted");refresh()})}
function actionButtons(id){return '<div class="actions"><button class="icon-btn" title="Edit" data-edit="'+id+'">✎</button><button class="icon-btn delete-btn" title="Delete" data-delete="'+id+'">⌫</button></div>'}
function modal(title,html,onSubmit){const wrap=document.createElement("div");wrap.className="modal-backdrop";wrap.innerHTML='<div class="modal"><div class="modal-top"><h2>'+title+'</h2><button class="icon-btn" id="close-modal">✕</button></div>'+html+'</div>';document.body.append(wrap);wrap.querySelector("#close-modal").onclick=()=>wrap.remove();wrap.addEventListener("click",e=>{if(e.target===wrap)wrap.remove()});const form=wrap.querySelector("form");if(form)form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('[type="submit"]');if(btn)btn.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));wrap.remove()}catch(x){fail(x);if(btn)btn.disabled=false}};return wrap}
function field(label,name,type="text",value="",required=false,extra=""){return '<label class="field"><span>'+label+'</span><input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(required?"required":"")+' '+extra+'></label>'}
function selectField(label,name,values,value){return '<label class="field"><span>'+label+'</span><select name="'+name+'">'+values.map(v=>'<option value="'+v+'" '+(v===value?"selected":"")+'>'+v.replaceAll("_"," ")+'</option>').join("")+'</select></label>'}
function area(label,name,value="",required=false){return '<label class="field full"><span>'+label+'</span><textarea name="'+name+'" '+(required?"required":"")+'>'+esc(value)+'</textarea></label>'}
function submit(label="Save changes"){return '<div class="form-actions"><button type="submit" class="btn btn-primary">'+label+'</button></div>'}
async function overview(){const [sv,sk,ld,ap,en]=await Promise.all([get("eb_services"),get("eb_skills"),get("eb_customer_leads"),get("eb_applications"),get("eb_earnings","earning_date")]);const received=en.filter(x=>x.payment_status==="received").reduce((a,x)=>a+Number(x.amount),0),pending=en.filter(x=>x.payment_status==="pending").reduce((a,x)=>a+Number(x.amount),0),active=ld.filter(x=>!["won","lost"].includes(x.stage)).length;let prof=await db.from("eb_profiles").select("full_name,headline").eq("id",user.id).maybeSingle();const name=prof.data?.full_name||user.email.split("@")[0];shell('<div class="welcome-banner"><div><span class="banner-tag">YOUR NEXT LEVEL STARTS HERE</span><h2>Good to see you, '+esc(name)+' 👋</h2><p>Build visibility, win customers and turn your skills into reliable income.</p><button class="btn btn-light" data-go="profile">Complete your profile →</button></div><div class="banner-art">↗<span>EB</span></div></div><div class="stats-grid">'+stat("Money received",money(received),"Confirmed income","↗")+stat("Awaiting payment",money(pending),"Outstanding income","◷")+stat("Active customer leads",active,"Potential clients","◎")+stat("Published services",sv.filter(x=>x.status==="published").length,"Offers customers can view","✦")+'</div><div class="section-row"><div><h2>Quick actions</h2><p>Move your business forward today.</p></div></div><div class="quick-grid"><button data-go="services"><b>＋</b><strong>Publish a service</strong><small>Show what you can offer</small></button><button data-go="leads"><b>◎</b><strong>Add a customer</strong><small>Track a new opportunity</small></button><button data-go="opportunities"><b>⌕</b><strong>Find work</strong><small>Explore income opportunities</small></button><button data-go="assistant"><b>✧</b><strong>Write a proposal</strong><small>Pitch your services clearly</small></button></div><div class="section-row"><div><h2>Keep building</h2><p>Complete these steps to improve your chances of earning.</p></div></div><div class="progress-list"><div><span>Professional profile</span><button class="text-btn" data-go="profile">Open profile →</button></div><div><span>Skills and experience</span><button class="text-btn" data-go="skills">Add your skills →</button></div><div><span>Services catalogue</span><button class="text-btn" data-go="services">Manage services →</button></div></div>');document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go))}
async function services(){const r=await get("eb_services");shell('<div class="toolbar"><input id="filter" placeholder="Search your services…"><button class="btn btn-primary" id="add">＋ Add service</button></div><div class="service-grid">'+(r.map(x=>'<div class="service-card"><div class="service-card-top"><span class="tag '+(x.status==="published"?"tag-green":"tag-amber")+'">'+esc(x.status)+'</span>'+actionButtons(x.id)+'</div><div class="service-symbol">✦</div><h3>'+esc(x.title)+'</h3><p>'+esc(x.description)+'</p><div class="service-bottom"><strong>'+money(x.price,x.currency)+'</strong><span>'+esc(x.pricing_type.replaceAll("_"," "))+'</span></div><small>'+esc(x.category||"General")+'</small></div>').join("")||empty("Your services start here","Add a service with a clear description and price, then publish it for customers.") )+'</div>');$("#add").onclick=()=>serviceForm();$("#filter").oninput=e=>document.querySelectorAll(".service-card").forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>serviceForm(r.find(x=>x.id===b.dataset.edit)));bindDelete("eb_services",services)}
function serviceForm(x={}){modal(x.id?"Edit service":"Create a service",'<form class="form-grid">'+field("Service title","title","text",x.title,true)+'<label class="field"><span>Category</span><input name="category" value="'+esc(x.category||"")+'" placeholder="e.g. Design, repairs, catering"></label>'+field("Price","price","number",x.price??"",false,'min="0" step="0.01"')+selectField("Currency","currency",["KES","USD","GBP","EUR","UGX","TZS","NGN"],x.currency||"KES")+selectField("Pricing model","pricing_type",["fixed","hourly","starting_at","custom"],x.pricing_type||"fixed")+selectField("Visibility","status",["draft","published","paused"],x.status||"published")+area("What will the customer receive?","description",x.description||"",true)+submit("Save service")+'</form>',async p=>{p.user_id=user.id;p.price=p.price?Number(p.price):null;const q=x.id?db.from("eb_services").update(p).eq("id",x.id):db.from("eb_services").insert(p);const {error}=await q;if(error)throw error;toast("Service saved");services()})}
async function skills(){const r=await get("eb_skills");shell('<div class="toolbar"><p class="toolbar-note">Add skills that match the work you want to win.</p><button class="btn btn-primary" id="add">＋ Add skill</button></div><div class="skill-grid">'+(r.map(x=>'<div class="skill-card"><div class="skill-card-head"><span class="skill-glyph">✧</span>'+actionButtons(x.id)+'</div><h3>'+esc(x.skill_name)+'</h3><span class="tag tag-green">'+esc(x.skill_level)+'</span><p>'+Number(x.years_experience||0)+' years experience</p></div>').join("")||empty("Make your skills visible","List practical skills, experience and strengths customers are looking for."))+'</div>');$("#add").onclick=()=>skillForm();document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>skillForm(r.find(x=>x.id===b.dataset.edit)));bindDelete("eb_skills",skills)}
function skillForm(x={}){modal(x.id?"Edit skill":"Add a skill",'<form class="form-grid">'+field("Skill name","skill_name","text",x.skill_name,true)+selectField("Skill level","skill_level",["beginner","intermediate","advanced","expert"],x.skill_level||"intermediate")+field("Years of experience","years_experience","number",x.years_experience??0,false,'min="0" max="60" step="0.5"')+submit(),async p=>{p.user_id=user.id;p.years_experience=Number(p.years_experience||0);const q=x.id?db.from("eb_skills").update(p).eq("id",x.id):db.from("eb_skills").insert(p);const {error}=await q;if(error)throw error;toast("Skill saved");skills()})}
async function leads(){const r=await get("eb_customer_leads");shell('<div class="toolbar"><input id="filter" placeholder="Search contacts or companies…"><button class="btn btn-primary" id="add">＋ Add lead</button></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Contact</th><th>Company</th><th>Stage</th><th>Potential value</th><th>Follow-up</th><th>Actions</th></tr></thead><tbody>'+(r.map(x=>'<tr><td><b>'+esc(x.contact_name)+'</b><small>'+esc(x.email||x.phone||"No contact details")+'</small></td><td>'+esc(x.company||"—")+'</td><td><span class="tag tag-blue">'+esc(x.stage.replaceAll("_"," "))+'</span></td><td>'+money(x.estimated_value,x.currency)+'</td><td>'+esc(x.next_follow_up||"—")+'</td><td>'+actionButtons(x.id)+'</td></tr>').join("")||'<tr><td colspan="6">'+empty("No customer leads yet","Add people or businesses who may need your service.")+'</td></tr>')+'</tbody></table></div></div>');$("#add").onclick=()=>leadForm();$("#filter").oninput=e=>document.querySelectorAll("tbody tr").forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>leadForm(r.find(x=>x.id===b.dataset.edit)));bindDelete("eb_customer_leads",leads)}
function leadForm(x={}){modal(x.id?"Edit customer lead":"Add customer lead",'<form class="form-grid">'+field("Contact name","contact_name","text",x.contact_name,true)+field("Company / business","company","text",x.company)+field("Email","email","email",x.email)+field("Phone","phone","tel",x.phone)+field("Estimated value","estimated_value","number",x.estimated_value??"") +selectField("Currency","currency",["KES","USD","GBP","EUR"],x.currency||"KES")+selectField("Pipeline stage","stage",["new","contacted","qualified","proposal_sent","won","lost"],x.stage||"new")+field("Next follow-up","next_follow_up","date",x.next_follow_up)+area("What do they need? / Notes","need_description",x.need_description)+submit(),async p=>{p.owner_id=user.id;p.estimated_value=p.estimated_value?Number(p.estimated_value):null;const q=x.id?db.from("eb_customer_leads").update(p).eq("id",x.id):db.from("eb_customer_leads").insert(p);const {error}=await q;if(error)throw error;toast("Customer lead saved");leads()})}
async function opportunities(){const [pub,own]=await Promise.all([db.from("eb_opportunities").select("*").eq("status","published").order("created_at",{ascending:false}),db.from("eb_opportunities").select("*").eq("created_by",user.id).order("created_at",{ascending:false})]);if(pub.error)throw pub.error;if(own.error)throw own.error;const all=pub.data||[],mine=own.data||[];shell('<div class="tabs"><button class="tab active" data-tab="discover">Discover work</button><button class="tab" data-tab="mine">My listings ('+mine.length+')</button></div><div id="opp-list"></div>');function show(which){document.querySelectorAll("[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===which));const list=which==="mine"?mine:all;$("#opp-list").innerHTML='<div class="toolbar">'+(which==="mine"?'<button class="btn btn-primary" id="post">＋ Post an opportunity</button>':'<input id="opp-search" placeholder="Search title, type or location…">')+'</div><div class="opportunity-grid">'+(list.map(x=>'<div class="opportunity-card"><div class="opp-top"><span class="tag '+(x.verification_status==="verified"?"tag-green":"tag-amber")+'">'+esc(x.verification_status)+'</span><span class="opp-type">'+esc(x.opportunity_type)+'</span></div><h3>'+esc(x.title)+'</h3><p class="opp-org">'+esc(x.organization||"Independent listing")+' · '+esc(x.country||"Remote / not specified")+'</p><p>'+esc(x.description)+'</p><div class="opp-meta">'+(x.budget_min||x.budget_max?money(x.budget_min||x.budget_max,x.currency):"Budget not specified")+' · '+(x.remote?"Remote":"On-site / flexible")+'</div>'+(which==="mine"?'<div class="opp-actions">'+actionButtons(x.id)+'</div>':'<button class="btn btn-primary apply-btn" data-apply="'+x.id+'">View & apply →</button>')+'</div>').join("")||empty(which==="mine"?"You haven't posted any opportunities":"No opportunities published yet","You can still build your profile and services while new listings are added.") )+'</div>'+(which==="discover"?'<p class="safety-note">⚠ Listings are not automatically verified. Verify the organisation and never pay an unexplained application or registration fee.</p>':"");if(which==="mine"){$("#post").onclick=()=>opportunityForm();document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>opportunityForm(mine.find(x=>x.id===b.dataset.edit)));bindDelete("eb_opportunities",opportunities)}else{$("#opp-search").oninput=e=>document.querySelectorAll(".opportunity-card").forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelectorAll("[data-apply]").forEach(b=>b.onclick=()=>applyForm(all.find(x=>x.id===b.dataset.apply)))}}
document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>show(b.dataset.tab));show("discover")}
function opportunityForm(x={}){modal(x.id?"Edit listing":"Publish an opportunity",'<form class="form-grid">'+field("Opportunity title","title","text",x.title,true)+field("Organisation / client","organization","text",x.organization)+selectField("Type","opportunity_type",["job","freelance","project","contract","grant","research","partnership","other"],x.opportunity_type||"project")+field("Category","category","text",x.category)+field("Country","country","text",x.country||"Kenya")+field("Currency","currency","text",x.currency||"KES") +field("Minimum budget","budget_min","number",x.budget_min)+field("Maximum budget","budget_max","number",x.budget_max)+field("Application link","application_url","url",x.application_url)+field("Contact email","contact_email","email",x.contact_email)+field("Deadline","deadline","date",x.deadline)+selectField("Work location","remote",["true","false"],String(x.remote??true))+selectField("Listing status","status",["draft","published","closed"],x.status||"published")+area("Full description","description",x.description||"",true)+submit("Publish listing")+'</form>',async p=>{p.created_by=user.id;p.remote=p.remote==="true";["budget_min","budget_max"].forEach(k=>p[k]=p[k]?Number(p[k]):null);const q=x.id?db.from("eb_opportunities").update(p).eq("id",x.id):db.from("eb_opportunities").insert(p);const {error}=await q;if(error)throw error;toast("Opportunity saved");opportunities()})}
function applyForm(x){modal("Apply for: "+esc(x.title),'<form class="form-grid">'+area("Why are you a good fit?","proposal","",true)+field("Your proposed amount","proposed_amount","number","",false,'min="0" step="0.01"')+field("Currency","currency","text",x.currency||"KES")+submit("Save application draft")+'</form>',async p=>{p.user_id=user.id;p.opportunity_id=x.id;p.proposed_amount=p.proposed_amount?Number(p.proposed_amount):null;p.status="draft";const {error}=await db.from("eb_applications").upsert(p,{onConflict:"user_id,opportunity_id"});if(error)throw error;toast("Application draft saved");go("applications")})}
async function applications(){const [a,s]=await Promise.all([db.from("eb_applications").select("*,eb_opportunities(title,organization)").order("created_at",{ascending:false}),db.from("eb_saved_opportunities").select("*,eb_opportunities(title,organization,description,opportunity_type)")]);if(a.error)throw a.error;if(s.error)throw s.error;const apps=a.data||[],saved=s.data||[];shell('<div class="tabs"><button class="tab active" data-tab="apps">My applications ('+apps.length+')</button><button class="tab" data-tab="saved">Saved opportunities ('+saved.length+')</button></div><div id="application-list"></div>');function show(t){document.querySelectorAll("[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===t));const list=t==="apps"?apps:saved;$("#application-list").innerHTML=list.length?'<div class="list-cards">'+list.map(x=>'<div class="list-card"><div><span class="tag tag-blue">'+esc(t==="apps"?x.status:"saved")+'</span><h3>'+esc(t==="apps"?(x.eb_opportunities?.title||"Opportunity"): (x.eb_opportunities?.title||"Opportunity"))+'</h3><p>'+esc(t==="apps"?(x.eb_opportunities?.organization||""):x.eb_opportunities?.description||"")+'</p>'+(t==="apps"?'<p class="muted">'+esc(x.proposal||"Draft proposal not written yet")+'</p>':"")+'</div>'+(t==="apps"?'<select class="status-select" data-status="'+x.id+'">'+["draft","submitted","viewed","shortlisted","rejected","accepted","withdrawn"].map(v=>'<option '+(v===x.status?"selected":"")+'>'+v+'</option>').join("")+'</select>':'<button class="btn btn-outline" data-unsave="'+x.opportunity_id+'">Remove saved</button>')+'</div>').join("")+'</div>':empty(t==="apps"?"No applications yet":"No saved opportunities","Find an opportunity and save it or prepare an application.");document.querySelectorAll("[data-status]").forEach(s=>s.onchange=async()=>{const {error}=await db.from("eb_applications").update({status:s.value,submitted_at:s.value==="submitted"?new Date().toISOString():null}).eq("id",s.dataset.status);if(error)fail(error);else toast("Application status updated")});document.querySelectorAll("[data-unsave]").forEach(b=>b.onclick=async()=>{const {error}=await db.from("eb_saved_opportunities").delete().eq("user_id",user.id).eq("opportunity_id",b.dataset.unsave);if(error)return fail(error);toast("Removed from saved");applications()})}document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>show(b.dataset.tab));show("apps")}
function assistant(){shell('<div class="studio-layout"><div class="studio-copy"><span class="tag tag-purple">SALES STUDIO</span><h2>Make your first impression count.</h2><p>Generate a polished outreach message, proposal or quotation using your own service details. Review and personalise before sending.</p><div class="studio-tip">✦ Tip: Be specific about the customer problem you solve and the result you deliver.</div></div><div class="studio-form"><label class="field"><span>What are you offering?</span><input id="pitch-service" placeholder="e.g. Website design, catering, cleaning"></label><label class="field"><span>Who is the customer?</span><input id="pitch-client" placeholder="e.g. A small shop in Nairobi"></label><label class="field"><span>What problem can you solve?</span><textarea id="pitch-problem" placeholder="Describe what the customer needs…"></textarea></label><label class="field"><span>Your strengths / experience</span><textarea id="pitch-strength" placeholder="Why should they trust you?"></textarea></label><label class="field"><span>Price / quote (optional)</span><input id="pitch-price" placeholder="e.g. KSh 5,000"></label><label class="field"><span>Message type</span><select id="pitch-type"><option value="intro">Introduction message</option><option value="proposal">Project proposal</option><option value="quote">Quotation message</option><option value="followup">Follow-up message</option></select></label><button class="btn btn-primary full-btn" id="generate">✧ Generate professional draft</button><label class="field output-label"><span>Your editable draft</span><textarea id="pitch-output" placeholder="Your message will appear here…"></textarea></label><button class="btn btn-outline" id="copy-pitch">Copy message</button></div></div>');$("#generate").onclick=()=>{const s=$("#pitch-service").value.trim()||"my services",c=$("#pitch-client").value.trim()||"your team",p=$("#pitch-problem").value.trim()||"your current needs",v=$("#pitch-strength").value.trim()||"reliable communication and quality delivery",price=$("#pitch-price").value.trim(),type=$("#pitch-type").value;let t;if(type==="proposal")t="PROJECT PROPOSAL\n\nHello "+c+",\n\nThank you for the opportunity to introduce my services. I propose to support you with "+s+".\n\nYour requirement: "+p+".\n\nMy approach and strengths: "+v+".\n\n"+(price?"Proposed investment: "+price+".\n\n":"")+"I would be happy to discuss the scope, timeline and next steps.\n\nKind regards";else if(type==="quote")t="QUOTATION MESSAGE\n\nHello "+c+",\n\nThank you for considering me for "+s+". Based on the details shared ("+p+"), my "+(price?"indicative quote is "+price:"quote can be prepared once the scope is confirmed")+".\n\nI bring "+v+". Please let me know if you would like me to proceed or clarify any details.\n\nKind regards";else if(type==="followup")t="FOLLOW-UP\n\nHello "+c+",\n\nI hope you are well. I am following up on my earlier message about "+s+". I would be glad to help with "+p+".\n\n"+v+". Please let me know if you have any questions or would like to discuss the next step.\n\nKind regards";else t="SERVICE INTRODUCTION\n\nHello "+c+",\n\nI am reaching out to introduce my "+s+" services. I can help with "+p+".\n\nWhat I bring: "+v+".\n\n"+(price?"My pricing starts at "+price+".\n\n":"")+"If this is something you need, I would be happy to discuss your requirements and provide more details.\n\nKind regards";$("#pitch-output").value=t};$("#copy-pitch").onclick=async()=>{if(!$("#pitch-output").value)return toast("Generate a draft first");try{await navigator.clipboard.writeText($("#pitch-output").value);toast("Message copied")}catch{ $("#pitch-output").select();toast("Select and copy the message")}}}
async function earnings(){const r=await get("eb_earnings","earning_date"),received=r.filter(x=>x.payment_status==="received").reduce((a,x)=>a+Number(x.amount),0),pending=r.filter(x=>x.payment_status==="pending").reduce((a,x)=>a+Number(x.amount),0);shell('<div class="stats-grid">'+stat("Received",money(received),"Money collected","↗")+stat("Outstanding",money(pending),"Still to be paid","◷")+stat("Income entries",r.length,"All records","▤")+'</div><div class="toolbar"><button class="btn btn-primary" id="add">＋ Record income</button></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Payment status</th><th>Actions</th></tr></thead><tbody>'+(r.map(x=>'<tr><td>'+esc(x.earning_date)+'</td><td><b>'+esc(x.description)+'</b></td><td>'+money(x.amount,x.currency)+'</td><td><span class="tag '+(x.payment_status==="received"?"tag-green":"tag-amber")+'">'+esc(x.payment_status)+'</span></td><td>'+actionButtons(x.id)+'</td></tr>').join("")||'<tr><td colspan="5">'+empty("No income recorded","Add payments you have received or are expecting.")+'</td></tr>')+'</tbody></table></div></div>');$("#add").onclick=()=>incomeForm();document.querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>incomeForm(r.find(x=>x.id===b.dataset.edit)));bindDelete("eb_earnings",earnings)}
function incomeForm(x={}){modal(x.id?"Edit income entry":"Record income",'<form class="form-grid">'+field("Description","description","text",x.description,true)+field("Amount","amount","number",x.amount??"",true,'min="0.01" step="0.01"')+selectField("Currency","currency",["KES","USD","GBP","EUR"],x.currency||"KES")+field("Date","earning_date","date",x.earning_date||new Date().toISOString().slice(0,10),true)+selectField("Payment status","payment_status",["pending","received","refunded","cancelled"],x.payment_status||"received")+field("Reference (optional)","external_reference","text",x.external_reference)+submit("Save income")+'</form>',async p=>{p.user_id=user.id;p.amount=Number(p.amount);const q=x.id?db.from("eb_earnings").update(p).eq("id",x.id):db.from("eb_earnings").insert(p);const {error}=await q;if(error)throw error;toast("Income saved");earnings()})}
async function profile(){const [pr,sk]=await Promise.all([db.from("eb_profiles").select("*").eq("id",user.id).maybeSingle(),get("eb_skills")]);if(pr.error)throw pr.error;const d=pr.data||{};shell('<div class="profile-layout"><div class="profile-preview"><div class="avatar">'+esc((d.full_name||user.email).slice(0,1).toUpperCase())+'</div><h2>'+esc(d.full_name||"Your name")+'</h2><p>'+esc(d.headline||"Add a professional headline")+'</p><span class="tag tag-green">'+esc(d.country||"Add your location")+'</span><div class="profile-count">'+sk.length+' skills listed</div></div><div class="profile-editor"><form id="profile-form" class="form-grid">'+field("Full name","full_name","text",d.full_name,true)+field("Country","country","text",d.country||"Kenya")+field("City","city","text",d.city)+selectField("Preferred currency","preferred_currency",["KES","USD","GBP","EUR","UGX","TZS"],d.preferred_currency||"KES")+field("Professional headline","headline","text",d.headline)+field("Phone","phone","tel",d.phone)+field("Website / portfolio","website_url","url",d.website_url)+selectField("Profile visibility","profile_visibility",["public","private"],d.profile_visibility||"public")+area("About your work and experience","bio",d.bio||"")+submit("Save profile")+'</form></div></div>');$("#profile-form").onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget));p.id=user.id;const {error}=await db.from("eb_profiles").upsert(p);if(error)return fail(error);toast("Profile updated");profile()}}
document.addEventListener("click",e=>{const b=e.target.closest("[data-go]");if(b)go(b.dataset.go)});
// Initialise from the persisted session once. Explicit sign-in/sign-out handlers below
// control the view; avoiding database work inside onAuthStateChange prevents auth-lock races.
const {data:{session},error:sessionError}=await db.auth.getSession();
if(sessionError){console.error("EarnBridge session check failed:",sessionError);showAuth()}
else if(session?.user){user=session.user;try{await ensureProfile()}catch(e){console.error("Profile initialisation:",e);toast("Signed in, but your profile needs attention: "+(e.message||"database setup"))}showApp()}
else showAuth();


